package com.mealflex.campaign.entity;
import com.mealflex.common.entity.BaseEntity; import com.mealflex.subscription.entity.Subscription; import com.mealflex.user.entity.User; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="campaign_redemptions") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class CampaignRedemption extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="campaign_id",nullable=false) private Campaign campaign; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="customer_id",nullable=false) private User customer; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subscription_id") private Subscription subscription; @Column(nullable=false) private BigDecimal discountAmount; }
